// Format a duration given in seconds as hours and minutes ("1h 30m", "45m").
// Seconds below a whole minute are dropped. Exact hours omit the minutes ("2h").
export function formatDuration(seconds) {
  if (!Number.isInteger(seconds) || seconds < 0) throw new RangeError('seconds must be a non-negative integer');
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  if (h === 0) return `${m}m`;
  if (m === 0) return `${h}h`;
  return `${h}h ${m}m`;
}

tests/duration.test.js.text:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { formatDuration } from '../src/duration.js';

test('hours and minutes', () => {
  assert.equal(formatDuration(5400), '1h 30m');
});

test('exact hours omit the minutes', () => {
  assert.equal(formatDuration(7200), '2h');
  // Seconds below a whole minute are dropped, so this is still zero minutes.
  assert.equal(formatDuration(3601), '1h');
});

test('minutes only', () => {
  assert.equal(formatDuration(2700), '45m');
  assert.equal(formatDuration(59), '0m');
});

test('a negative or fractional duration is an error', () => {
  assert.throws(() => formatDuration(-1), RangeError);
  assert.throws(() => formatDuration(1.5), RangeError);
});
